#import <Foundation/Foundation.h>

@interface Calculator : NSObject
- (int)add:(int)a to:(int)b;
+ (int)square:(int)n;
@end

@implementation Calculator
- (int)add:(int)a to:(int)b {
    return a + b;
}
+ (int)square:(int)n {
    return n * n;
}
@end

int main(void) {
    @autoreleasepool {
        Calculator *calc = [[Calculator alloc] init];
        printf("%d\n", [calc add:2 to:3]);
        printf("%d\n", [Calculator square:7]);
    }
    return 0;
}

#import <Foundation/Foundation.h>

@interface Counter : NSObject
- (void)increment;
- (int)value;
@end

@implementation Counter {
    int _count;
}
- (void)increment {
    _count++;
}
- (int)value {
    return _count;
}
@end

int main(void) {
    @autoreleasepool {
        Counter *a = [[Counter alloc] init];
        [a increment];
        [a increment];
        [a increment];
        Counter *b = [[Counter alloc] init];
        printf("%d %d\n", [a value], [b value]);
    }
    return 0;
}

#import <Foundation/Foundation.h>

@interface Greeter : NSObject
- (instancetype)initWithName:(NSString *)name;
- (void)greet;
@end

@implementation Greeter {
    NSString *_name;
}
- (instancetype)initWithName:(NSString *)name {
    self = [super init];
    if (self) {
        _name = name;
    }
    return self;
}
- (void)greet {
    printf("Hello, %s!\n", [_name UTF8String]);
}
@end

int main(void) {
    @autoreleasepool {
        Greeter *g = [[Greeter alloc] initWithName:@"Ada"];
        [g greet];
    }
    return 0;
}

